// Process analytics data and match with blog posts
const blogPosts = $('Supabase - Get Recent Published Posts').all();
const analyticsData = $('HTTP Request - Google Analytics Data').first().json;
const searchConsoleData = $('HTTP Request - Search Console Data').first().json;
const leads = $('Supabase - Get Recent Leads').all();

// Process Google Analytics data
const gaRows = analyticsData.reports?.[0]?.data?.rows || [];
const scRows = searchConsoleData.rows || [];

// Create performance data for each blog post
const performanceMetrics = blogPosts.map(post => {
  const postSlug = post.json.slug;
  const postPath = `/blog/${postSlug}`;

  // Find matching GA data
  const gaRow = gaRows.find(row => row.dimensions[0] === postPath);
  const scRow = scRows.find(row => row.keys[0] === `https://alpinepeakroofing.com${postPath}`);

  // Extract metrics
  const pageViews = gaRow ? parseInt(gaRow.metrics[0].values[0]) : 0;
  const bounceRate = gaRow ? parseFloat(gaRow.metrics[0].values[1]) : 0;
  const avgTimeOnPage = gaRow ? parseInt(gaRow.metrics[0].values[2]) : 0;
  const goalCompletions = gaRow ? parseInt(gaRow.metrics[0].values[3]) : 0;

  const clicks = scRow ? scRow.clicks : 0;
  const impressions = scRow ? scRow.impressions : 0;
  const ctr = scRow ? scRow.ctr : 0;
  const position = scRow ? scRow.position : 0;

  // Calculate estimated leads from this post (basic attribution)
  const estimatedLeads = Math.round(goalCompletions * 0.3); // 30% of goals attributed to blog

  return {
    blog_post_id: post.json.id,
    page_views: pageViews,
    bounce_rate: Math.round(bounceRate * 100) / 100,
    time_on_page: avgTimeOnPage,
    leads_generated: estimatedLeads,
    social_shares: 0, // Would need to integrate with social APIs
    click_through_rate: Math.round(ctr * 10000) / 100, // Convert to percentage
    conversion_rate: goalCompletions > 0 ? Math.round((estimatedLeads / pageViews) * 10000) / 100 : 0,
    search_impressions: impressions,
    search_clicks: clicks,
    search_position: Math.round(position * 10) / 10,
    measured_at: new Date().toISOString()
  };
});

// Calculate top and low performers
const sortedByViews = [...performanceMetrics].sort((a, b) => b.page_views - a.page_views);
const topPerformers = sortedByViews.slice(0, 3);
const lowPerformers = sortedByViews.slice(-3);

// Calculate total metrics
const totalPageViews = performanceMetrics.reduce((sum, metric) => sum + metric.page_views, 0);
const totalLeads = performanceMetrics.reduce((sum, metric) => sum + metric.leads_generated, 0);
const avgBounceRate = performanceMetrics.length > 0 
  ? performanceMetrics.reduce((sum, metric) => sum + metric.bounce_rate, 0) / performanceMetrics.length 
  : 0;

return {
  json: {
    performance_metrics: performanceMetrics,
    summary: {
      total_posts_analyzed: performanceMetrics.length,
      total_page_views: totalPageViews,
      total_leads_generated: totalLeads,
      average_bounce_rate: Math.round(avgBounceRate * 100) / 100,
      top_performers: topPerformers.map(p => ({
        blog_post_id: p.blog_post_id,
        page_views: p.page_views,
        leads: p.leads_generated
      })),
      low_performers: lowPerformers.map(p => ({
        blog_post_id: p.blog_post_id,
        page_views: p.page_views,
        leads: p.leads_generated
      }))
    },
    analysis_date: new Date().toISOString()
  }
};
